import re

def resolve(text, variables, properties):
    def prop(m):
        name, default = m.group(1), m.group(3)
        if name in properties:
            return properties[name]
        return default if default is not None else '1'
    text = re.sub(r'\$\{__P\(([^,)]+)(,([^)]*))?\)\}', prop, text)
    return re.sub(r'\$\{(\w+)\}', lambda m: variables.get(m.group(1), m.group(0)), text)

class Jmeter:
    def __init__(self):
        self.props = {}
        self._vars = {}

    def vars_for(self, thread_id):
        return self._vars.setdefault(thread_id, {})
